import { DetailsOfBook } from "./DetailsBook";
import { useSelector, useDispatch } from "react-redux";
import { EditBooks } from "./Edit-books";
import { AddBooks } from "./Add-books";
import React from "react";
import { SortBooksModal } from "./modals/SortBooksModal";
function MainContext() {
  const stateAddBooksModal = useSelector((state) => state.books.modalAddOpen);
  const stateDetailsBook = useSelector((state) => state.books.detailsOpen);
  const stateEditBook = useSelector((state) => state.books.editOpen);

  return (
    <React.Fragment>
      {stateAddBooksModal && <AddBooks />}
      {stateDetailsBook && <DetailsOfBook />}
      {stateEditBook && <EditBooks />}
      {/* <SortBooksModal /> */}
    </React.Fragment>
  );
}
export { MainContext };
