import { useDispatch } from "react-redux";
import { closeDetailsBook } from "../reducers/bookSlice";
import { useSelector } from "react-redux";
import { toggleEditBook } from "../reducers/bookSlice";
import { deleteBook } from "../reducers/bookSlice";
import { labels } from "../units/rating.ts";
import {
  Box,
  AppBar,
  Button,
  Stack,
  Typography,
  useTheme,
} from "@mui/material";
import Divider from "@mui/material/Divider";
import CloseTwoToneIcon from "@mui/icons-material/CloseTwoTone";
import { addInActiveBook } from "../reducers/bookSlice";
import { setBackInActiveBooks } from "../reducers/bookSlice";
import { Link } from "react-router-dom";
import KeyboardBackspaceOutlinedIcon from "@mui/icons-material/KeyboardBackspaceOutlined";
import PrintTwoToneIcon from "@mui/icons-material/PrintTwoTone";
import DrawIcon from "@mui/icons-material/Draw";
import { Rating } from "@mui/material";
import { getLabelText } from "../units/rating.ts";
import EventAvailableIcon from "@mui/icons-material/EventAvailable";
import { createTheme, responsiveFontSizes } from "@mui/material";
import { ThemeProvider } from "@emotion/react";

function DetailsOfBook() {
  const selectBook = useSelector((state) => state.books.selectedBook);
  const ratingValue = useSelector((state) => state.books.rating);
  const ratingHover = useSelector((state) => state.books.ratingHover);
  const theme = useTheme();
  const stateInActiveBook = useSelector(
    (state) => state.books.stateInActiveBook
  );
  const dispatch = useDispatch();

  let responsive = createTheme();
  responsive = responsiveFontSizes(responsive);

  return (
    <div className="container">
      <AppBar
        sx={{
          p: 2,
          display: "flex",
          alignItems: "center",
          gap: "16px",
          flexDirection: "row",
        }}
      >
        <div
          style={{ display: "flex", alignItems: "center" }}
          onClick={() => dispatch(closeDetailsBook())}
        >
          <KeyboardBackspaceOutlinedIcon
            sx={{ color: useTheme().palette.primary.light }}
          />
        </div>
        <Typography
          sx={{ color: useTheme().palette.primary.light }}
          variant="h5"
        >
          Про книги
        </Typography>
      </AppBar>
      <CloseTwoToneIcon
        sx={{ position: "absolute", top: "20px", right: "20px" }}
        onClick={() => dispatch(closeDetailsBook())}
      />

      <div className="details-container">
        <Box textAlign={"center"}>
          <ThemeProvider theme={responsive}>
            <Typography sx={{ m: 2 }} variant="h4">
              {selectBook.name}
            </Typography>
            <Typography variant="h5">
              {selectBook.series}
              {selectBook.part && `(${selectBook.part})`}
            </Typography>
          </ThemeProvider>
        </Box>
        <Box
          sx={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: "30px",
          }}
        >
          <Box width={"30%"}>
            <img
              width={"100%"}
              src={
                selectBook.poster.name
                  ? localStorage.getItem([selectBook.poster.name])
                  : selectBook.poster
                  ? selectBook.poster
                  : `${process.env.PUBLIC_URL}/image/book.png`
              }
            />
          </Box>
          <Box width={"70%"}>
            <Box sx={{ display: "flex", alignItems: "center", gap: "20px" }}>
              <PrintTwoToneIcon color="secondary" fontSize="large" />
              <Typography>{selectBook.publish}</Typography>
            </Box>
            <Box sx={{ display: "flex", alignItems: "center", gap: "20px" }}>
              <DrawIcon color="secondary" fontSize="large" />
              <Typography>
                {selectBook.firstName} {selectBook.lastName}
              </Typography>
            </Box>
            <Box sx={{ display: "flex", alignItems: "center", gap: "20px" }}>
              <EventAvailableIcon color="secondary" fontSize="large" />
              <Typography>{selectBook.date}</Typography>
            </Box>
          </Box>
        </Box>
        <Box
          sx={{
            "& > legend": { m: 2 },
            alignSelf: "center",
            m: 3,
            display: "flex",
            alignItems: "center",
            gap: "12px",
          }}
        >
          <Rating
            size="large"
            name="rating"
            precision={0.5}
            value={ratingValue}
            getLabelText={getLabelText}
          />
          {ratingValue !== null && (
            <Box sx={{ ml: 2, color: "#ffb30e" }}>
              {labels[ratingHover !== -1 ? ratingHover : ratingValue]}
            </Box>
          )}
        </Box>
        {selectBook.folder && (
          <div className="detailseField">
            <span>Полиця:</span> <span>{selectBook.folder}</span>
          </div>
        )}
        {selectBook.page && (
          <div className="detailseField">
            <span>Кількість сторінок:</span> <span>{selectBook.page}</span>
          </div>
        )}
        {selectBook.language && (
          <div className="detailseField">
            <span>Мова:</span> <span>{selectBook.language}</span>
          </div>
        )}
        {selectBook.price && (
          <div className="detailseField">
            <span>Ціна:</span> <span>{selectBook.price} грн</span>
          </div>
        )}
        {selectBook.genre && (
          <div className="detailseField">
            <span>Жанр:</span> <span>{selectBook.genre}</span>
          </div>
        )}
        {selectBook.rezume && (
          <div className="detailseField">
            <span>Резюме:</span>{" "}
            <span style={{ textAlign: "justify" }}>
              <i>{selectBook.rezume}</i>
            </span>
          </div>
        )}
        <Box
          sx={{
            my: 3,
            position: "sticky",
            bottom: "0",
            zIndex: "0",
          }}
        >
          {stateInActiveBook ? (
            <Stack
              sx={{ justifyContent: "center", alignItems: "flex-end" }}
              direction="row"
              spacing={2}
              divider={<Divider orientation="vertical" flexItem />}
            >
              <Button
                sx={{ color: theme.palette.primary.light }}
                variant="contained"
                onClick={() => {
                  dispatch(setBackInActiveBooks());
                }}
                type="button"
              >
                Повернути до списку книг
              </Button>
            </Stack>
          ) : (
            <Stack
              sx={{ justifyContent: "center", alignItems: "flex-end" }}
              direction="row"
              spacing={2}
              divider={<Divider orientation="vertical" flexItem />}
            >
              <Button
                sx={{ color: theme.palette.primary.light }}
                variant="contained"
                type="button"
                onClick={() => dispatch(toggleEditBook())}
              >
                редагувати
              </Button>
              <Button
                sx={{ color: theme.palette.primary.light }}
                variant="contained"
                type="button"
                onClick={() => dispatch(deleteBook())}
              >
                видалити
              </Button>
              <Button
                sx={{ color: theme.palette.primary.light }}
                variant="contained"
                onClick={() => dispatch(addInActiveBook())}
                type="button"
              >
                <Link
                  style={{ color: theme.palette.primary.light }}
                  to="inActive"
                >
                  Позичити
                </Link>
              </Button>
            </Stack>
          )}
        </Box>
      </div>
    </div>
  );
}
export { DetailsOfBook };
