import ReactDOM from "react-dom";
import { useDispatch } from "react-redux";
import { editFolder } from "../../reducers/folderSlice";
import { useSelector } from "react-redux";
import { toggleEditFolderModal } from "../../reducers/folderSlice";
import { updateNameFolder } from "../../reducers/bookSlice";
import Dialog from "@mui/material/Dialog";
import {
  Button,
  DialogActions,
  DialogContent,
  DialogTitle,
} from "@mui/material";
import { useTheme } from "@emotion/react";
import TextField from "@mui/material/TextField";
import React from "react";
import { useState } from "react";
import { addErrorNameFolder } from "../../reducers/optionslice";

function ModalEditFolder() {
  const [folderName, setFolderName] = useState("");
  const folders = useSelector((state) => state.libraryfolder.folder);
  const errorNameFolder = useSelector((state) => state.options.errorNameFolder);
  const stateEditFolder = useSelector(
    (state) => state.libraryfolder.modalEditOpen
  );
  const selectFolder = useSelector(
    (state) => state.libraryfolder.selectedFolder
  );

  const handleEditFolder = (editData) => dispatch(editFolder(editData));

  const dispatch = useDispatch();

  const handleSubmit = (e) => {
    e.preventDefault();
    const indexFolder = folders
      .filter((item) => item.id !== selectFolder.id)
      .findIndex((e) => e.name === folderName.trim());
    const formData = new FormData(e.target);
    const data = Object.fromEntries(formData);
    if (!folderName.trim()) {
      dispatch(addErrorNameFolder("Поле обов'язкове для введення"));
      return;
    }
    if (indexFolder > -1) {
      dispatch(addErrorNameFolder("Ця назва вже існує"));
      return;
    }
    dispatch(updateNameFolder({ ...data, oldName: selectFolder.name }));
    handleEditFolder(data);
    dispatch(addErrorNameFolder(""));
    setFolderName("");
  };

  const handleCloseEdit = () => {
    setFolderName("");
    dispatch(toggleEditFolderModal());
    dispatch(addErrorNameFolder(""));
  };

  const handleFolderNameChange = (e) => {
    setFolderName(e.target.value);
    const index = folders
      .filter((item) => item.id !== selectFolder.id)
      .findIndex((el) => el.name === e.target.value.trim());
    if (selectFolder.name === e.target.value.trim()) {
      dispatch(addErrorNameFolder(""));
    }
    if (index > -1) {
      dispatch(addErrorNameFolder("Ця назва вже існує"));
    } else if (index < 0) dispatch(addErrorNameFolder(""));
  };

  return ReactDOM.createPortal(
    <React.Fragment>
      <Dialog
        open={stateEditFolder}
        onClose={() => dispatch(toggleEditFolderModal())}
        slotProps={{
          paper: {
            component: "form",
            noValidate: true,
            sx: {
              backgroundColor: useTheme().palette.background,
              padding: "20px",
            },
            onSubmit: (e) => {
              handleSubmit(e);
            },
          },
        }}
      >
        <DialogTitle>Змінити назву полиці </DialogTitle>
        <DialogContent>
          <TextField
            sx={{
              "& .MuiInputLabel-root.Mui-error": {
                color: "#e9bf06",
              },
              "& .MuiFormLabel-asterisk.Mui-error": {
                color: "#e9bf06",
              },
              "& .MuiFormLabel-asterisk": {
                color: "#e9bf06",
              },
              "& .MuiOutlinedInput-root.Mui-error .MuiOutlinedInput-notchedOutline":
                {
                  border: "3px solid #e9bf06",
                },
              "& .MuiInput-root.Mui-error::before": {
                borderBottomColor: "#e9bf06",
              },
              "& .MuiInput-root.Mui-error::after": {
                borderBottomColor: "#e9bf06",
              },
              "& .MuiFormHelperText-root.Mui-error": {
                color: "#e9bf06",
              },
            }}
            autoFocus
            defaultValue={selectFolder.name}
            onChange={handleFolderNameChange}
            required
            placeholder={selectFolder.name}
            error={errorNameFolder}
            margin="dense"
            id="name"
            name="newName"
            label="Нова назва"
            type="text"
            fullWidth
            value={folderName}
            variant="standard"
            helperText={errorNameFolder}
          />
        </DialogContent>
        <DialogActions>
          <Button variant="outlined" type="button" onClick={handleCloseEdit}>
            Відмінити
          </Button>
          <Button type="submit" variant="outlined">
            Змінити
          </Button>
        </DialogActions>
      </Dialog>
    </React.Fragment>,
    document.getElementById("modal-root")
  );
}
export { ModalEditFolder };
