import React from "react";
import { useSelector } from "react-redux";
import { ModalFormFolder } from "./modals/Modal-add-folder";
import { useDispatch } from "react-redux";
import { removeFolder } from "../reducers/folderSlice";
import { ModalDetailsFolder } from "./modals/modal-details-folder";
import { toggleDetails } from "../reducers/folderSlice";
import { changeActiveFolder } from "../reducers/folderSlice";
import { useOutsideClick } from "../hooks/useOutsideClick";
import { toggleAddModal } from "../reducers/folderSlice";
import "./styled/folders.css";
import { ModalEditFolder } from "./modals/Modal-edit-folder";
import { toggleListBooks } from "../reducers/folderSlice";
import { filtereFolders } from "../units/filtrerElements";
import MoreVertIcon from "@mui/icons-material/MoreVert";
import { Paper } from "@mui/material";
import { useTheme } from "@emotion/react";
import { folderStyle } from "./styled/folderClasses";
import { clsx } from "clsx";
import { Box } from "@mui/material";
import Fab from "@mui/material/Fab";
import AddIcon from "@mui/icons-material/Add";
import { NavLink } from "react-router-dom";
import HomeIcon from "@mui/icons-material/Home";
import { deleteBooksFromFolder } from "../reducers/bookSlice";
function Folders() {
  const theme = useTheme();
  const classes = folderStyle();
  const dispatch = useDispatch();
  const folders = useSelector((state) => state.libraryfolder.folder);
  const detailsOpen = useSelector((state) => state.libraryfolder.detailsOpen);
  const statebooks = useSelector((state) => state.books.book);
  const stateView = useSelector((state) => state.options.view);
  const stateAddFolderModal = useSelector(
    (state) => state.libraryfolder.modalAddOpen
  );
  const selectFolderID = useSelector(
    (state) => state.libraryfolder.selectedFolderId
  );
  const sortState = useSelector((state) => state.options.sortOptions);
  const searchValue = useSelector((state) => state.books.searchValue);

  useOutsideClick(() => {
    if (detailsOpen) setTimeout(() => dispatch(toggleDetails()), 50);
  });

  const onclickRemoveFolder = (folder) => {
    dispatch(removeFolder(folder.id));
    dispatch(deleteBooksFromFolder(folder.name));
  };

  const onClickToggleModal = () => {
    dispatch(toggleAddModal());
  };

  const onClickToggleDetails = (item) => {
    dispatch(toggleDetails());
    dispatch(changeActiveFolder(item));
  };

  const onClickToggleBooks = (selectFolder) => {
    dispatch(toggleListBooks());
    dispatch(changeActiveFolder(selectFolder));
  };

  const filteredFolders = filtereFolders(folders, searchValue);
  const booksOfFolders = (el) => {
    return statebooks.filter((item) => item.folder === el.name);
  };

  const contextMenu = (e, item) => {
    e.preventDefault();
    onClickToggleDetails(item);
  };

  const sortedFolders = [...filteredFolders].sort((a, b) => {
    if (a.name < b.name) {
      return sortState.sortOrder ? -1 : 1;
    }
    if (a.name > b.name) {
      return !sortState.sortOrder ? 1 : -1;
    }
  });
  return (
    <div>
      <Paper
        elevation={1}
        sx={{
          p: 1,
          backgroundColor: theme.palette.background,
          color: theme.palette.secondary.main,
          display: "flex",
          gap: 1,
          alignItems: "center",
        }}
      >
        <HomeIcon />

        <span>Полиці</span>
      </Paper>
      {filteredFolders.length < 1 && (
        <Paper
          elevation={1}
          sx={{
            my: 3,
            py: 4,
            backgroundColor: theme.palette.background,
            display: "flex",
            flexDirection: "column",
          }}
          className="view-block"
        >
          <Box>
            <img src={`${process.env.PUBLIC_URL}/image/books8.png`} />
          </Box>
          <Box>Перелік полиць порожній</Box>
        </Paper>
      )}
      {stateView ? (
        <Box>
          {sortedFolders.map((item) => (
            <Paper
              elevation={2}
              sx={{ my: 3, backgroundColor: theme.palette.background }}
              className="view-block"
            >
              <NavLink
                className={classes.link}
                to={`${item.id}`}
                activeClassName="active"
              >
                <div
                  style={{ display: "flex", alignItems: "center", gap: "20px" }}
                >
                  <div>
                    <img
                      width="80px"
                      src={`${process.env.PUBLIC_URL}/image/shelf.png`}
                    />
                  </div>
                  <div onClick={() => onClickToggleBooks(item)} key={item.id}>
                    <div>{item.name}</div>
                    <div style={{ color: theme.palette.secondary.main }}>
                      книг: {booksOfFolders(item).length}
                    </div>
                  </div>
                </div>{" "}
              </NavLink>
              <MoreVertIcon
                onClick={() => onClickToggleDetails(item)}
              ></MoreVertIcon>
              <Paper
                className={clsx(
                  classes.paper,
                  detailsOpen &&
                    selectFolderID === item.id &&
                    classes.modalIsOpen
                )}
                elevation={2}
                sx={{ transition: "300ms" }}
              >
                <ModalDetailsFolder onClickRemove={onclickRemoveFolder} />
              </Paper>
            </Paper>
          ))}
        </Box>
      ) : (
        <Box className={classes.fields}>
          {sortedFolders.map((item) => (
            <Paper
              elevation={2}
              onContextMenu={(e) => contextMenu(e, item)}
              sx={{
                backgroundColor: theme.palette.background,
                flexDirection: "column",
              }}
              className="view-block"
            >
              <NavLink
                className={classes.link}
                style={{ textAlign: "center" }}
                to={`${item.id}`}
                activeClassName="active"
              >
                <div>
                  <img
                    width="100%"
                    src={`${process.env.PUBLIC_URL}/image/shelf.png`}
                  />
                </div>
                <div onClick={() => onClickToggleBooks(item)} key={item.id}>
                  {item.name}
                  <div style={{ color: theme.palette.secondary.main }}>
                    книг: {booksOfFolders(item).length}
                  </div>
                </div>
              </NavLink>
              <Paper
                className={clsx(
                  classes.paper,
                  detailsOpen &&
                    selectFolderID === item.id &&
                    classes.modalIsOpen
                )}
                elevation={2}
                sx={{ transition: "300ms" }}
              >
                <ModalDetailsFolder onClickRemove={onclickRemoveFolder} />
              </Paper>
            </Paper>
          ))}
        </Box>
      )}

      <Box
        sx={{
          m: 3,
          position: "sticky",
          right: "20px",
          textAlign: "end",
          bottom: "20px",
        }}
      >
        <Fab
          size="medium"
          color="primary"
          sx={{ color: theme.palette.primary.light }}
          aria-label="add"
          onClick={onClickToggleModal}
        >
          <AddIcon />
        </Fab>
      </Box>

      <ModalFormFolder
        stateAddFolderModal={stateAddFolderModal}
        onCloseModal={onClickToggleModal}
      />

      <ModalEditFolder />
    </div>
  );
}
export { Folders };
