import { useDispatch, useSelector } from "react-redux";
import { openDetailsBook } from "../reducers/bookSlice";
import { toggleAddBooksModal } from "../reducers/bookSlice";
import { filterElements } from "../units/filtrerElements";
import { Paper, useTheme, Box, Fab, Typography } from "@mui/material";
import { clsx } from "clsx";
import { folderStyle } from "./styled/folderClasses";
import AddIcon from "@mui/icons-material/Add";
import { useNavigate } from "react-router-dom";
import KeyboardArrowRightIcon from "@mui/icons-material/KeyboardArrowRight";
import HomeIcon from "@mui/icons-material/Home";

function Books() {
  const dispatch = useDispatch();
  const statebooks = useSelector((state) => state.books.book);
  const searchValue = useSelector((state) => state.books.searchValue);
  const sortState = useSelector((state) => state.options.sortOptions);
  const selectBook = useSelector((state) => state.books.selectedBook);

  const stateView = useSelector((state) => state.options.view);

  const classes = folderStyle();
  const theme = useTheme();
  const filteredBooks = filterElements(statebooks, searchValue);
  const sortedBooks = [...filteredBooks].sort((a, b) => {
    if (a[sortState.sort] < b[sortState.sort]) {
      return sortState.sortOrder === "asc" ? -1 : 1;
    }
    if (a[sortState.sort] > b[sortState.sort]) {
      return sortState.sortOrder === "desc" ? -1 : 1;
    }
  });
  let navigate = useNavigate();
  const handleBackClick = () => {
    navigate("/");
  };
  return (
    <div>
      <Paper
        onClick={handleBackClick}
        elevation={1}
        sx={{
          p: 1,
          backgroundColor: theme.palette.background,
          color: theme.palette.secondary.main,
          display: "flex",
          alignItems: "center",
        }}
      >
        <HomeIcon />
        <KeyboardArrowRightIcon />
        <span>Книги</span>
      </Paper>
      {filteredBooks.length < 1 && (
        <Paper
          elevation={1}
          sx={{
            my: 3,
            py: 4,
            backgroundColor: theme.palette.background,
            display: "flex",
            flexDirection: "column",
          }}
          className="view-block"
        >
          <Box>
            <img src={`${process.env.PUBLIC_URL}/image/books8.png`} />
          </Box>
          <Box>Перелік книг порожній</Box>
        </Paper>
      )}
      {stateView ? (
        <Box>
          {sortedBooks.map((el) => (
            <Paper
              elevation={2}
              sx={{ my: 3, backgroundColor: theme.palette.background }}
              className="view-block"
              onClick={() => dispatch(openDetailsBook(el))}
            >
              <Box sx={{ display: "flex", gap: "20px", alignItems: "center" }}>
                <Box sx={{ width: "100px", p: 1 }}>
                  <img
                    width={"100%"}
                    src={
                      el.poster.name
                        ? localStorage.getItem([el.poster.name])
                        : el.poster
                        ? el.poster
                        : `${process.env.PUBLIC_URL}/image/book.png`
                    }
                  />
                </Box>
                <Box>
                  <Typography>{el.name}</Typography>
                  <Typography sx={{ color: theme.palette.secondary.main }}>
                    <i>
                      {el.firstName} {el.lastName}
                    </i>
                  </Typography>
                </Box>
              </Box>
              <Box sx={{ color: theme.palette.secondary.main }}>
                <Typography>{el.date}</Typography>
                <Typography>cторінок: {el.page}</Typography>
              </Box>
            </Paper>
          ))}
        </Box>
      ) : (
        <Box className={classes.fields}>
          {sortedBooks.map((el) => (
            <Paper
              elevation={2}
              className="view-block"
              sx={{
                backgroundColor: theme.palette.background,
                flexDirection: "column",
                justifyContent: "center",
              }}
              onClick={() => dispatch(openDetailsBook(el))}
            >
              <Box>
                <img
                  width="100%"
                  src={
                    el.poster.name
                      ? localStorage.getItem([el.poster.name])
                      : el.poster
                      ? el.poster
                      : `${process.env.PUBLIC_URL}/image/book.png`
                  }
                />
              </Box>
              <Typography variant="h7" textAlign={"center"}>
                {el.name}
              </Typography>
            </Paper>
          ))}
        </Box>
      )}

      <Box
        sx={{
          m: 3,
          position: "sticky",
          right: "20px",
          textAlign: "end",
          bottom: "20px",
        }}
      >
        <Fab
          size="medium"
          color="primary"
          sx={{ color: theme.palette.primary.light }}
          aria-label="add"
          onClick={() => dispatch(toggleAddBooksModal())}
        >
          <AddIcon />
        </Fab>
      </Box>
    </div>
  );
}

export { Books };
