import { useSelector, useDispatch } from "react-redux";
import { openDetailsBook } from "../reducers/bookSlice";
import { toggleInActiveBook } from "../reducers/bookSlice";
import { Box, Paper, Typography } from "@mui/material";
import { folderStyle } from "./styled/folderClasses";
import { useTheme } from "@emotion/react";
import { filterElements } from "../units/filtrerElements";
import KeyboardArrowRightIcon from "@mui/icons-material/KeyboardArrowRight";
import HomeIcon from "@mui/icons-material/Home";
import { useNavigate } from "react-router-dom";
function InActiveBook() {
  const listInActiveBooks = useSelector(
    (state) => state.books.listInActiveBooks
  );
  const stateInActiveBook = useSelector(
    (state) => state.books.stateInActiveBook
  );
  const stateView = useSelector((state) => state.options.view);
  const searchValue = useSelector((state) => state.books.searchValue);
  const sortState = useSelector((state) => state.options.sortOptions);

  const classes = folderStyle();
  const theme = useTheme();
  const dispatch = useDispatch();

  const handleClickDetails = (item) => {
    dispatch(toggleInActiveBook());
    dispatch(openDetailsBook(item));
  };
  const filteredInActiveBooks = filterElements(listInActiveBooks, searchValue);

  const sortedBooks = [...filteredInActiveBooks].sort((a, b) => {
    if (a[sortState.sort] < b[sortState.sort]) {
      return sortState.sortOrder === "asc" ? -1 : 1;
    }
    if (a[sortState.sort] > b[sortState.sort]) {
      return sortState.sortOrder === "desc" ? -1 : 1;
    }
  });

  let navigate = useNavigate();
  const handleBackClick = () => {
    navigate("/");
  };

  return (
    <div>
      <Paper
        onClick={handleBackClick}
        elevation={1}
        sx={{
          p: 1,
          backgroundColor: theme.palette.background,
          color: theme.palette.secondary.main,
          display: "flex",
          alignItems: "center",
        }}
      >
        <HomeIcon />
        <KeyboardArrowRightIcon />
        <span>Позичено</span>
      </Paper>
      {filteredInActiveBooks.length < 1 && (
        <Paper
          elevation={1}
          sx={{
            my: 3,
            py: 4,
            backgroundColor: theme.palette.background,
            display: "flex",
            flexDirection: "column",
          }}
          className="view-block"
        >
          <Box>
            <img src={`${process.env.PUBLIC_URL}/image/books8.png`} />
          </Box>
          <Box>Перелік книг порожній</Box>
        </Paper>
      )}
      {stateView ? (
        <Box>
          {sortedBooks.map((el) => (
            <Paper
              elevation={2}
              sx={{ my: 3, backgroundColor: theme.palette.background }}
              className="view-block"
              onClick={() => {
                handleClickDetails(el);
              }}
            >
              <Box sx={{ display: "flex", gap: "20px", alignItems: "center" }}>
                <Box sx={{ width: "100px", p: 1 }}>
                  <img
                    width={"100%"}
                    src={
                      el.poster.name
                        ? localStorage.getItem([el.poster.name])
                        : el.poster
                        ? el.poster
                        : `${process.env.PUBLIC_URL}/image/book.png`
                    }
                  />
                </Box>
                <Box>
                  <Typography>{el.name}</Typography>
                  <Typography sx={{ color: theme.palette.secondary.main }}>
                    <i>
                      {el.firstName} {el.lastName}
                    </i>
                  </Typography>
                </Box>
              </Box>
              <Box sx={{ color: theme.palette.secondary.main }}>
                <Typography>{el.date}</Typography>
                <Typography>cторінок: {el.page}</Typography>
              </Box>
            </Paper>
          ))}
        </Box>
      ) : (
        <Box className={classes.fields}>
          {sortedBooks.map((el) => (
            <Paper
              onClick={() => {
                handleClickDetails(el);
              }}
              elevation={2}
              sx={{
                backgroundColor: theme.palette.background,
                flexDirection: "column",
              }}
              className="view-block"
            >
              <Box sx={{ width: "100px", p: 1 }}>
                <img
                  width={"100%"}
                  src={
                    el.poster.name
                      ? localStorage.getItem([el.poster.name])
                      : el.poster
                      ? el.poster
                      : `${process.env.PUBLIC_URL}/image/book.png`
                  }
                />
              </Box>
              <Typography textAlign={"center"}>{el.name}</Typography>
            </Paper>
          ))}
        </Box>
      )}
    </div>
  );
}
export { InActiveBook };
