import { Dialog, FormLabel, RadioGroup } from "@mui/material";
import React from "react";
import { Radio } from "@mui/material";
import { FormControlLabel } from "@mui/material";
import { FormControl } from "@mui/material";
import { useSelector } from "react-redux";
import { toggleSortBooksModal } from "../../reducers/optionslice";
import { useDispatch } from "react-redux";
import { useTheme } from "@emotion/react";
import { DialogActions } from "@mui/material";
import { Button } from "@mui/material";
import { upDateSortOptions } from "../../reducers/optionslice";
import { Divider } from "@mui/material";

function SortBooksModal() {
  const sortBooksOpen = useSelector((state) => state.options.sortBooksOpen);
  const dispatch = useDispatch();

  const handleClose = () => {
    dispatch(toggleSortBooksModal(false));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    const obj = Object.fromEntries(formData);
    dispatch(upDateSortOptions(obj));
    handleClose();
  };

  return (
    <React.Fragment>
      <Dialog
        maxWidth="lg"
        open={sortBooksOpen}
        onClose={handleClose}
        slotProps={{
          paper: {
            component: "form",
            noValidate: true,
            sx: {
              backgroundColor: useTheme().palette.background,
              p: 4,
              m: 4,
            },

            onSubmit: (e) => {
              handleSubmit(e);
            },
          },
        }}
      >
        <FormControl
          sx={{ display: "flex", flexDirection: "column", gap: "20px" }}
        >
          <div>
            <FormLabel id="sort">Сортувати книги</FormLabel>
            <RadioGroup aria-labelledby="sort" defaultValue="name" name="sort">
              <FormControlLabel
                value="name"
                control={<Radio />}
                label="Назва"
              />
              <FormControlLabel
                value="lastName"
                control={<Radio />}
                label="Прізвище автора"
              />
              <FormControlLabel
                value="firstName"
                control={<Radio />}
                label="Ім'я автора"
              />
              <FormControlLabel
                value="publish"
                control={<Radio />}
                label="Видавництво"
              />
              <FormControlLabel
                value="date"
                control={<Radio />}
                label="Дата публікації"
              />
              <FormControlLabel
                value="page"
                control={<Radio />}
                label="Сторінки"
              />
              <FormControlLabel
                value="rating"
                control={<Radio />}
                label="Рейтинг"
              />
              <FormControlLabel
                value="price"
                control={<Radio />}
                label="Ціна"
              />
            </RadioGroup>
          </div>
          <Divider />
          <div>
            <FormLabel id="sortOrder">Порядок сортування</FormLabel>
            <RadioGroup
              aria-labelledby="sortOrder"
              defaultValue="asc"
              name="sortOrder"
            >
              <FormControlLabel
                value="asc"
                control={<Radio />}
                label="По порядку зростання"
              />
              <FormControlLabel
                value="desc"
                control={<Radio />}
                label="По порядку спадання"
              />
            </RadioGroup>
          </div>
        </FormControl>
        <DialogActions>
          <Button onClick={handleClose}>Відмінити</Button>
          <Button type="submit">OK</Button>
        </DialogActions>
      </Dialog>
    </React.Fragment>
  );
}
export { SortBooksModal };
