import { NavLink } from "react-router-dom";
import { useSelector } from "react-redux";
import { useDispatch } from "react-redux";
import { onChangeSearchValue } from "../reducers/bookSlice";
import React from "react";
import AppBar from "@mui/material/AppBar";
import Typography from "@mui/material/Typography";
import MenuIcon from "@mui/icons-material/Menu";
import SearchIcon from "@mui/icons-material/Search";
import { onchangeView } from "../reducers/optionslice";
import { MenuItems } from "./modals/MenuItems";
import SpaIcon from "@mui/icons-material/Spa";
import {
  Container,
  Toolbar,
  InputBase,
  useTheme,
  TextField,
} from "@mui/material";
import ViewListIcon from "@mui/icons-material/ViewList";
import GridViewIcon from "@mui/icons-material/GridView";
import { Box } from "@mui/material";
import { headerStyle } from "./styled/headerClasses";
import SortIcon from "@mui/icons-material/Sort";
import { toggleSortBooksModal } from "../reducers/optionslice";
import { useLocation } from "react-router-dom";
import { SortBooksModal } from "./modals/SortBooksModal";
import { upDateSortOptions } from "../reducers/optionslice";
import FilterListIcon from "@mui/icons-material/FilterList";
import SwapVertIcon from "@mui/icons-material/SwapVert";
import { createTheme, responsiveFontSizes } from "@mui/material";
import { ThemeProvider } from "@emotion/react";

function Header() {
  const stateView = useSelector((state) => state.options.view);
  const dispatch = useDispatch();
  const classes = headerStyle();
  const sortState = useSelector((state) => state.options.sortOptions);
  const theme = useTheme();

  let responsive = createTheme();
  responsive = responsiveFontSizes(responsive);

  const [open, setOpen] = React.useState(false);

  const handleDrawerOpen = () => {
    setOpen(true);
  };

  const location = useLocation();

  const handleDrawerClose = () => {
    setOpen(false);
  };

  const onOpenSortModal = () => {
    if (location.pathname !== "/") {
      dispatch(toggleSortBooksModal(true));
    } else {
      dispatch(toggleSortBooksModal(false));
      dispatch(
        upDateSortOptions({ sort: "name", sortOrder: !sortState.sortOrder })
      );
    }
  };
  return (
    <>
      <AppBar sx={{ p: 2 }} position="relative">
        <Container>
          <Toolbar variant="h3" sx={{ justifyContent: "space-between" }}>
            <div className={classes.menuButton} onClick={handleDrawerOpen}>
              <MenuIcon
                fontSize="large"
                sx={{ m: 2, color: theme.palette.primary.light }}
              />
            </div>
            <div className={classes.title}>
              <SpaIcon
                fontSize="large"
                sx={{ m: 1, color: theme.palette.primary.light }}
              />
              <ThemeProvider theme={responsive}>
                <Typography variant="h5">Literary treasury</Typography>
              </ThemeProvider>
            </div>

            <div className={classes.search}>
              <div className={classes.searchIcon}>
                <SearchIcon
                  sx={{
                    m: 2,
                    color: useTheme().palette.primary.light,
                  }}
                />
              </div>
              <InputBase
                sx={{ color: useTheme().palette.secondary.dark }}
                classes={{
                  root: classes.inputRoot,
                  input: classes.inputInput,
                }}
                placeholder="Search…"
                onChange={(e) => dispatch(onChangeSearchValue(e.target.value))}
              />
            </div>
            <SortIcon
              className={!sortState.sortOrder && classes.rotateIcon}
              onClick={onOpenSortModal}
              sx={{ m: 2, color: useTheme().palette.primary.light }}
              fontSize="large"
            />
            {stateView ? (
              <ViewListIcon
                onClick={() => dispatch(onchangeView())}
                sx={{ m: 2, color: theme.palette.primary.light }}
                fontSize="large"
              />
            ) : (
              <GridViewIcon
                onClick={() => dispatch(onchangeView())}
                sx={{ m: 2, color: theme.palette.primary.light }}
                fontSize="large"
              />
            )}
          </Toolbar>
          <Box className={classes.menuItems}>
            <div>
              <NavLink
                className={classes.link}
                to="/"
                exact
                activeClassName="active"
              >
                Полиці
              </NavLink>
            </div>
            <div>
              <NavLink
                className={classes.link}
                to="books"
                exact
                activeClassName="active"
              >
                Книги
              </NavLink>
            </div>
            <div>
              <NavLink
                className={classes.link}
                to="inActive"
                exact
                activeClassName="active"
              >
                Позичено
              </NavLink>
            </div>
          </Box>
        </Container>
      </AppBar>
      <MenuItems handleDrawerClose={handleDrawerClose} open={open} />
      <SortBooksModal />
    </>
  );
}
export { Header };
