import ReactDOM from "react-dom";
import { useDispatch } from "react-redux";
import { addFolder } from "../../reducers/folderSlice";
import Dialog from "@mui/material/Dialog";
import { useState } from "react";
import {
  Button,
  DialogActions,
  DialogContent,
  DialogTitle,
} from "@mui/material";
import TextField from "@mui/material/TextField";
import { useTheme } from "@emotion/react";
import React from "react";
import { addErrorNameFolder } from "../../reducers/optionslice";
import { useSelector } from "react-redux";

function ModalFormFolder({ stateAddFolderModal, onCloseModal }) {
  const folders = useSelector((state) => state.libraryfolder.folder);
  const errorNameFolder = useSelector((state) => state.options.errorNameFolder);
  const [folderName, setFolderName] = useState("");
  const dispatch = useDispatch();

  const handleAddFolder = (date) => dispatch(addFolder(date));

  const handleSubmit = (e) => {
    e.preventDefault();
    const indexFolder = folders.findIndex((e) => e.name === folderName.trim());
    const formData = new FormData(e.target);
    const obj = Object.fromEntries(formData);
    const data = { ...obj, id: Date.now() };
    if (!folderName.trim()) {
      dispatch(addErrorNameFolder("Поле обов'язкове для введення"));
      return;
    }
    if (indexFolder > -1) {
      dispatch(addErrorNameFolder("Ця назва вже існує"));
      return;
    }
    handleAddFolder(data);
    dispatch(addErrorNameFolder(""));
    onCloseModal();
    setFolderName("");
    dispatch(addErrorNameFolder(""));
  };

  const handleCloseModal = () => {
    setFolderName("");
    dispatch(addErrorNameFolder(""));
    onCloseModal();
  };

  const handleFolderNameChange = (e) => {
    setFolderName(e.target.value);
    const index = folders.findIndex((el) => el.name === e.target.value.trim());
    if (index > -1) {
      dispatch(addErrorNameFolder("Ця назва вже існує"));
    } else if (index < 0) dispatch(addErrorNameFolder(""));
  };

  return ReactDOM.createPortal(
    <React.Fragment>
      <Dialog
        open={stateAddFolderModal}
        onClose={() => onCloseModal()}
        noValidate
        slotProps={{
          paper: {
            component: "form",
            noValidate: true,
            sx: {
              backgroundColor: useTheme().palette.background,
              padding: "20px",
            },

            onSubmit: (e) => {
              handleSubmit(e);
            },
          },
        }}
      >
        <DialogTitle>Додати нову полицю </DialogTitle>
        <DialogContent>
          <TextField
            sx={{
              "& .MuiInputLabel-root.Mui-error": {
                color: "#e9bf06",
              },
              "& .MuiFormLabel-asterisk.Mui-error": {
                color: "#e9bf06",
              },
              "& .MuiFormLabel-asterisk": {
                color: "#e9bf06",
              },
              "& .MuiOutlinedInput-root.Mui-error .MuiOutlinedInput-notchedOutline":
                {
                  border: "3px solid #e9bf06",
                },
              "& .MuiInput-root.Mui-error::before": {
                borderBottomColor: "#e9bf06",
              },
              "& .MuiInput-root.Mui-error::after": {
                borderBottomColor: "#e9bf06",
              },
              "& .MuiFormHelperText-root.Mui-error": {
                color: "#e9bf06",
              },
            }}
            autoFocus
            onChange={handleFolderNameChange}
            required
            error={errorNameFolder}
            margin="dense"
            id="name"
            name="name"
            label="Назва"
            type="text"
            fullWidth
            value={folderName}
            variant="standard"
            helperText={errorNameFolder}
          />
        </DialogContent>
        <DialogActions>
          <Button variant="outlined" type="button" onClick={handleCloseModal}>
            Відмінити
          </Button>
          <Button type="submit" variant="outlined">
            Додати
          </Button>
        </DialogActions>
      </Dialog>
    </React.Fragment>,
    document.getElementById("modal-root")
  );
}
export { ModalFormFolder };
