import { useTheme } from "@emotion/react";
import { makeStyles } from "@mui/styles";

const drawerWidth = 240;

export const MenuItemsStyle = makeStyles((theme) => ({
  root: { display: "flex" },
  appBar: {
    transition: useTheme().transitions.create(["margin", "width"], {
      easing: useTheme().transitions.easing.sharp,
      duration: useTheme().transitions.duration.leavingScreen,
    }),
  },
  appBarShift: {
    width: `calc(100% - ${drawerWidth}px)`,
    marginLeft: drawerWidth,
    transition: useTheme().transitions.create(["margin", "width"], {
      easing: useTheme().transitions.easing.easeOut,
      duration: useTheme().transitions.duration.enteringScreen,
    }),
  },
  //   menuButton: {
  //     marginRight: useTheme().spacing(2),
  //   },

  drawer: {
    width: drawerWidth,
    flexShrink: 0,
  },
  drawerPaper: {
    width: drawerWidth,
    backgroundColor: useTheme().palette.background,
  },
  drawerHeader: {
    display: "flex",
    alignItems: "center",
    padding: useTheme().spacing(0, 1),
    // necessary for content to be below app bar
    ...useTheme().mixins.toolbar,
    justifyContent: "flex-end",
  },
  content: {
    flexGrow: 1,
    padding: useTheme().spacing(3),
    transition: useTheme().transitions.create("margin", {
      easing: useTheme().transitions.easing.sharp,
      duration: useTheme().transitions.duration.leavingScreen,
    }),
    marginLeft: -drawerWidth,
  },
  contentShift: {
    transition: useTheme().transitions.create("margin", {
      easing: useTheme().transitions.easing.easeOut,
      duration: useTheme().transitions.duration.enteringScreen,
    }),
    marginLeft: 0,
  },
  listItem: {
    gap: useTheme().spacing(4),
    color: useTheme().palette.secondary.dark,
  },
  link: {
    color: useTheme().palette.secondary.dark,
  },
  active: {
    color: useTheme().palette.primary.dark,
  },
}));
